-- Phase 10 payroll numeric hardening
begin;
alter table public.employee_monthly_payroll alter column crm_incentive_percentage type numeric(9,4),alter column basic type numeric(18,2),alter column hra type numeric(18,2),alter column allowance type numeric(18,2),alter column other_earnings type numeric(18,2),alter column fixed_gross type numeric(18,2),alter column payable_basic type numeric(18,2),alter column payable_hra type numeric(18,2),alter column payable_allowance type numeric(18,2),alter column payable_other_earnings type numeric(18,2),alter column attendance_salary type numeric(18,2),alter column crm_eligible_amount type numeric(18,2),alter column crm_incentive_amount type numeric(18,2),alter column overtime_amount type numeric(18,2),alter column adjustment_amount type numeric(18,2),alter column net_payable type numeric(18,2);
alter table public.payroll_crm_incentive_details alter column eligible_amount type numeric(18,2);
create or replace function public.update_payroll_variables(p_id uuid,p_percentage numeric,p_overtime numeric,p_adjustment numeric,p_reason text)returns void language plpgsql security definer set search_path=''as $$declare x public.employee_monthly_payroll%rowtype;new_incentive numeric(18,2);new_net numeric(18,2);begin if not public.has_erp_permission('hr-payroll.monthly_payroll','EDIT')then raise exception'Monthly Payroll edit permission required';end if;select * into x from public.employee_monthly_payroll where id=p_id and status in('DRAFT','REOPENED')for update;if not found then raise exception'Editable payroll not found';end if;if p_percentage<0 or p_percentage>100 or p_overtime<0 or(p_adjustment<>0 and nullif(trim(p_reason),'')is null)then raise exception'Incentive percentage must be 0–100, overtime cannot be negative, and adjusted payroll requires a reason';end if;new_incentive:=round((x.crm_eligible_amount::numeric*p_percentage::numeric)/100::numeric,2);new_net:=round(x.attendance_salary::numeric+new_incentive+p_overtime::numeric+p_adjustment::numeric,2);update public.employee_monthly_payroll set crm_incentive_percentage=round(p_percentage,4),crm_incentive_amount=new_incentive,overtime_amount=round(p_overtime,2),adjustment_amount=round(p_adjustment,2),adjustment_reason=nullif(trim(p_reason),''),net_payable=new_net,updated_by=auth.uid(),updated_at=now()where id=p_id;insert into public.payroll_audit(payroll_run_id,payroll_id,event_type,old_value,new_value,reason)values(x.payroll_run_id,p_id,'PAYROLL_UPDATED',jsonb_build_object('percentage',x.crm_incentive_percentage,'overtime',x.overtime_amount,'adjustment',x.adjustment_amount),jsonb_build_object('percentage',p_percentage,'overtime',p_overtime,'adjustment',p_adjustment),p_reason);end$$;
commit;
